Please run the following Python code to load the Excel file and calculate the number of missing qualifications per applicant, using the six requirements listed:

import pandas as pd

path = './workdir/Applicants.xlsx'
df = pd.read_excel(path)

allowed_fields = {'Biology', 'Biochemistry', 'Biotechnology'}
allowed_levels = {'Masters', 'PhD'}
allowed_langs = {'C++', 'C#', 'Fortran'}

def missing_count(row):
    missing = 0
    # Degree Level and Field
    if (row['Degree Level'] not in allowed_levels) or (row['Degree Field'] not in allowed_fields):
        missing += 1
    # Experience
    if row['Experience (Years)'] < 3:
        missing += 1
    # Lab Trained
    if str(row['Lab Trained (Y/N)']).strip().upper() != 'Y':
        missing += 1
    # Publications
    if row['Publications'] < 3:
        missing += 1
    # Citizenship
    if str(row['Citizen (Y/N)']).strip().upper() != 'Y':
        missing += 1
    # Programming language
    if str(row['Programming Lang']).strip() not in allowed_langs:
        missing += 1
    return missing

df['Missing Qualifications'] = df.apply(missing_count, axis=1)
count_exactly_one = (df['Missing Qualifications'] == 1).sum()
print(f'Number of applicants missing exactly one qualification: {count_exactly_one}')

